// Выполнение Python Lead Agent
const { exec } = require('child_process');
const util = require('util');
const execPromise = util.promisify(exec);

const userMessage = $input.item.json.user_message;
const agentPath = '/home/user/2026/lead_agent';

// Экранируем кавычки в сообщении
const escapedMessage = userMessage.replace(/"/g, '\\"');

// Python скрипт для вызова агента
const pythonScript = `
import sys
import json
sys.path.append('${agentPath}')

try:
    from agent import LeadCollectionAgent
    agent = LeadCollectionAgent()
    response = agent.process_message("${escapedMessage}")
    print(json.dumps({"success": True, "response": response}))
except Exception as e:
    print(json.dumps({"success": False, "error": str(e)}))
`;

// Сохраняем во временный файл
const fs = require('fs');
const tempFile = `/tmp/lead_agent_${Date.now()}.py`;
fs.writeFileSync(tempFile, pythonScript);

try {
  const { stdout, stderr } = await execPromise(
    `cd ${agentPath} && source venv/bin/activate && python ${tempFile}`,
    { shell: '/bin/bash', timeout: 300000 }
  );

  fs.unlinkSync(tempFile);

  try {
    const result = JSON.parse(stdout.trim());
    return {
      success: result.success,
      response: result.response || result.error,
      user_message: userMessage,
      timestamp: new Date().toISOString()
    };
  } catch (parseError) {
    return {
      success: true,
      response: stdout.trim(),
      user_message: userMessage,
      timestamp: new Date().toISOString()
    };
  }

} catch (error) {
  if (fs.existsSync(tempFile)) {
    fs.unlinkSync(tempFile);
  }

  return {
    success: false,
    response: `Ошибка при выполнении агента: ${error.message}`,
    user_message: userMessage,
    timestamp: new Date().toISOString()
  };
}

// Определяем тип ответа и добавляем кнопки если нужно
const response = $input.item.json.response;
const userMessage = $input.item.json.user_message.toLowerCase();

// Проверяем нужны ли кнопки
let needsButtons = false;
let buttonType = '';

// Если в ответе упоминается завершение сбора сайтов
if (response.includes('сайт') && (response.includes('добавлен') || response.includes('собран') || response.includes('найден'))) {
  needsButtons = true;
  buttonType = 'collect_data';
}

// Если в ответе упоминается завершение сбора данных
if (response.includes('данные собраны') || response.includes('информация собрана') || response.includes('компани') && response.includes('обработан')) {
  needsButtons = true;
  buttonType = 'generate_letters';
}

// Если в ответе упоминается создание писем
if (response.includes('письм') && (response.includes('создан') || response.includes('сгенерирован'))) {
  needsButtons = true;
  buttonType = 'complete';
}

return {
  response: response,
  needs_buttons: needsButtons,
  button_type: buttonType,
  chat_id: $('Extract Message Data').item.json.chat_id
};

